import sys; sys.path.insert(0,'.'); from lib import *
d=load_base(); y=labels()
M=lambda l: d[f'mean_hidden_L{l}'][:,KEEP]; Cc=lambda l: d[f'cls_hidden_L{l}'][:,KEEP]
def krr_cv(K, y, lams, k=5, seeds=(0,1)):
    out={}; Y=np.eye(8)[y]
    for lam in lams:
        accs=[]
        for seed in seeds:
            f=folds(y,k,seed); S=np.zeros((len(y),8))
            for i in range(k):
                tr=f!=i; te=f==i
                A=np.linalg.solve(K[np.ix_(tr,tr)]+lam*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0)); S[te]=K[np.ix_(te,tr)]@A
            accs.append((S.argmax(1)==y).mean())
        out[lam]=round(float(np.mean(accs)),4)
    return out
def rbf(X,gf=1):
    Xs=X-X.mean(0); sq=(Xs**2).sum(1); D2=sq[:,None]+sq[None,:]-2*Xs@Xs.T
    return np.exp(-D2/(gf*np.median(D2)))
def blockn(Xs): return np.concatenate([(x-x.mean(0))/np.sqrt(((x-x.mean(0))**2).sum(1).mean()) for x in Xs],1)
for j in [3,4,5,6,7,8,9,10,12]:
    sel=sorted(set([0, j//2, j]))
    r1=krr_cv(rbf(blockn([M(l) for l in sel]+[Cc(j)])),y,(0.003,0.01))
    r2=krr_cv(rbf(blockn([M(j),Cc(j)])),y,(0.003,0.01))
    r3=cv_acc(blockn([M(l) for l in sel]+[Cc(j)]),y,lams=(0.03,0.1,0.3))
